#!/bin/sh
# Runs from postCreateCommand (cwd = workspace folder). Generated by create_devcontainer.sh.
set -e

git config --global user.name "Joni Hasanen"
git config --global user.email "joni@pieceofcode.com"
if [ -n "F6FBD66B087C9160" ]; then
  git config --global user.signingkey "F6FBD66B087C9160"
  git config --global commit.gpgsign true
fi
git config --global --add safe.directory "$PWD"

# History prefix search on up/down.
grep -qs history-search-backward ~/.inputrc || printf '"\\e[A": history-search-backward\n"\\e[B": history-search-forward\n"\\eOA": history-search-backward\n"\\eOB": history-search-forward\n' >> ~/.inputrc

grep -qs devcontainer/prompt.sh ~/.bashrc || echo ". $PWD/.devcontainer/prompt.sh" >> ~/.bashrc
